package shop;

public class ShippingPolicy {
    static final long FREE_FROM = 500_000;
    static final long FEE = 30_000;

    public long fee(long orderTotal, boolean vip) {
        if (vip || orderTotal > FREE_FROM) {
            return 0;
        }
        return FEE;
    }
}

class ShippingPolicyTest {
    private final ShippingPolicy policy = new ShippingPolicy();

    @Test
    void bigOrderShipsFree() {
        assertEquals(0, policy.fee(800_000, false));
    }

    @Test
    void smallOrderPaysFee() {
        assertEquals(30_000, policy.fee(120_000, false));
    }

    @Test
    void vipShipsFree() {
        assertEquals(0, policy.fee(120_000, true));
    }
}

fix.code:
public long fee(long orderTotal, boolean vip) {
    if (vip || orderTotal >= FREE_FROM) {
        return 0;
    }
    return FEE;
}

class ShippingPolicyBoundaryTest {
    private final ShippingPolicy policy = new ShippingPolicy();

    @ParameterizedTest(name = "{0}đ -> phí {1}")
    @CsvSource({"499999, 30000", "500000, 0", "500001, 0"})
    void freeShippingStartsAt500k(long total, long expectedFee) {
        assertEquals(expectedFee, policy.fee(total, false));
    }
}
